// Hàm mã hóa payload dữ liệu để bảo mật mã nguồn offline
function encodePayload(jsonStr: string): string {
  try {
    const bytes = new TextEncoder().encode(jsonStr);
    let bin = '';
    const chunk = 8192;
    for (let i = 0; i < bytes.length; i += chunk) {
      bin += String.fromCharCode(...bytes.subarray(i, i + chunk));
    }
    const b64 = typeof window !== 'undefined' && window.btoa
      ? window.btoa(bin)
      : (typeof (globalThis as any).Buffer !== 'undefined'
          ? (globalThis as any).Buffer.from(bytes).toString('base64')
          : '');
    return b64.split('').reverse().join('');
  } catch (err) {
    console.error('encodePayload error:', err);
    return '';
  }
}

// Base64 chuẩn của Logo Agribank (gốc từ src/assets/logo-agribank.png)
export const AGRIBANK_LOGO_BASE64 = `data:image/png;base64,`;

export function toSafeBase64DataUri(svgOrUri: string): string {
  if (!svgOrUri) return '';
  if (svgOrUri.startsWith('data:image/png;base64,') || svgOrUri.startsWith('data:image/jpeg;base64,')) {
    return svgOrUri;
  }
  let rawSvg = svgOrUri;
  if (rawSvg.startsWith('data:image/svg+xml;base64,')) {
    try {
      const b64Part = rawSvg.replace('data:image/svg+xml;base64,', '');
      const decodedStr = typeof window !== 'undefined' && window.atob 
        ? decodeURIComponent(escape(window.atob(b64Part)))
        : (typeof (globalThis as any).Buffer !== 'undefined' ? (globalThis as any).Buffer.from(b64Part, 'base64').toString('utf8') : '');
      if (decodedStr) rawSvg = decodedStr;
    } catch {}
  } else if (rawSvg.startsWith('data:image/svg+xml;utf8,')) {
    rawSvg = rawSvg.replace('data:image/svg+xml;utf8,', '');
  }
  try {
    try {
      rawSvg = decodeURIComponent(rawSvg);
    } catch {}
    rawSvg = rawSvg.replace(/%23/g, '#');
    const encoded = typeof window !== 'undefined' && window.btoa 
      ? window.btoa(unescape(encodeURIComponent(rawSvg)))
      : (typeof (globalThis as any).Buffer !== 'undefined' ? (globalThis as any).Buffer.from(rawSvg).toString('base64') : '');
    return `data:image/svg+xml;base64,${encoded}`;
  } catch {
    return svgOrUri;
  }
}

function escapeHtml(str: any): string {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const removeAccents = (str: string) => {
  return str
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D');
};

export const getColorFromText = (text: string) => {
  const colors = ['#AE1C3F', '#2563EB', '#059669', '#D97706', '#7C3AED', '#DC2626', '#0891B2', '#4F46E5', '#9333EA', '#EA580C'];
  let hash = 0;
  for (let i = 0; i < text.length; i++) hash = text.charCodeAt(i) + ((hash << 5) - hash);
  return colors[Math.abs(hash) % colors.length];
};

export const formatDateDot = (dateString?: string | null) => {
  if (!dateString) return '---';
  try {
    const d = new Date(dateString);
    if (isNaN(d.getTime())) return dateString;
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    return `${day}.${month}.${year}`;
  } catch {
    return dateString;
  }
};

const formatDate = (dateString?: string | null) => {
  if (!dateString) return '---';
  try {
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return dateString;
    const d = String(date.getDate()).padStart(2, '0');
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const y = date.getFullYear();
    return `${d}/${m}/${y}`;
  } catch {
    return dateString;
  }
};

export const formatFullDateTimeVi = (dateInput?: string | number | Date | null): string => {
  if (!dateInput) return '';
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return '';
  const hours = String(d.getHours()).padStart(2, '0');
  const minutes = String(d.getMinutes()).padStart(2, '0');
  const seconds = String(d.getSeconds()).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${hours} giờ ${minutes} phút ${seconds} giây, ngày ${day} tháng ${month} năm ${year}`;
};

