  <script>
    // Hàm giải mã dữ liệu an toàn trong bộ nhớ RAM (hỗ trợ 100% mọi trình duyệt và thiết bị)
    function _decodePayload(str) {
      if (!str) return [];
      try {
        var b64 = str.split('').reverse().join('');
        var bin = atob(b64);
        var bytes = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) {
          bytes[i] = bin.charCodeAt(i);
        }
        var json = (typeof TextDecoder !== 'undefined')
          ? new TextDecoder('utf-8').decode(bytes)
          : decodeURIComponent(escape(bin));
        return JSON.parse(json);
      } catch (e) {
        console.warn('Decode payload error:', e);
        return [];
      }
    }

    var OFFLINE_PRODUCTS = _decodePayload("${encProducts}");
    var OFFLINE_GROUPS = _decodePayload("${encGroups}");
    var OFFLINE_CATEGORIES = _decodePayload("${encCategories}");
    var OFFLINE_BUSINESSES = _decodePayload("${encBusinesses}");
    var INITIAL_SAVED_IDS = _decodePayload("${encInitialSavedIds}");

    // Hàm loại bỏ dấu tiếng Việt an toàn tuyệt đối trên mọi trình duyệt (kể cả iOS QuickLook)
    function removeAccents(str) {
      if (!str) return '';
      str = String(str);
      try {
        if (typeof str.normalize === 'function') {
          str = str.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        }
      } catch (e) {}
      var vMap = {
        'à':'a','á':'a','ả':'a','ã':'a','ạ':'a','ă':'a','ằ':'a','ắ':'a','ẳ':'a','ẵ':'a','ặ':'a','â':'a','ầ':'a','ấ':'a','ẩ':'a','ẫ':'a','ậ':'a',
        'è':'e','é':'e','ẻ':'e','ẽ':'e','ẹ':'e','ê':'e','ề':'e','ế':'e','ể':'e','ễ':'e','ệ':'e',
        'ì':'i','í':'i','ỉ':'i','ĩ':'i','ị':'i',
        'ò':'o','ó':'o','ỏ':'o','õ':'o','ọ':'o','ô':'o','ồ':'o','ố':'o','ổ':'o','ỗ':'o','ộ':'o','ơ':'o','ờ':'o','ớ':'o','ở':'o','ỡ':'o','ợ':'o',
        'ù':'u','ú':'u','ủ':'u','ũ':'u','ụ':'u','ư':'u','ừ':'u','ứ':'u','ử':'u','ữ':'u','ự':'u',
        'ỳ':'y','ý':'y','ỷ':'y','ỹ':'y','ỵ':'y',
        'đ':'d','Đ':'d'
      };
      return str.replace(/[^A-Za-z0-9]/g, function(x) { return vMap[x] || x; }).toLowerCase().replace(/\s+/g, ' ').trim();
    }

    function escapeText(str) {
      return (str || '').replace(/[&<>"']/g, function(m) {
        return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[m];
      });
    }

    function formatDateVi(iso) {
      if (!iso) return '';
      var d = new Date(iso);
      if (isNaN(d.getTime())) return '';
      var dd = String(d.getDate()).padStart(2, '0');
      var mm = String(d.getMonth() + 1).padStart(2, '0');
      var yyyy = d.getFullYear();
      return dd + '.' + mm + '.' + yyyy;
    }

    function highlightText(text, query) {
      if (!query || !query.trim()) return escapeText(text);
      var q = query.trim();
      try {
        var escapedQ = q;
        var specialChars = ['\\\\', '^', '$', '.', '*', '+', '?', '(', ')', '[', ']', '{', '}', '|'];
        for (var sc = 0; sc < specialChars.length; sc++) {
          escapedQ = escapedQ.split(specialChars[sc]).join('\\\\' + specialChars[sc]);
        }
        var regex = new RegExp('(' + escapedQ + ')', 'gi');
        if (regex.test(text)) {
          var parts = text.split(regex);
          var res = '';
          for (var i = 0; i < parts.length; i++) {
            if (parts[i].toLowerCase() === q.toLowerCase()) {
              res += '<span class="highlight-text">' + escapeText(parts[i]) + '</span>';
            } else {
              res += escapeText(parts[i]);
            }
          }
          return res;
        }
      } catch (e) {}

      var qNorm = removeAccents(q);
      var srcNorm = removeAccents(text);
      var idx = srcNorm.indexOf(qNorm);
      if (idx !== -1 && idx < text.length) {
        var before = text.slice(0, idx);
        var match = text.slice(idx, Math.min(text.length, idx + q.length));
        var after = text.slice(idx + q.length);
        return escapeText(before) + '<span class="highlight-text">' + escapeText(match) + '</span>' + escapeText(after);
      }
      return escapeText(text);
    }

    // =========================================================================
    // QUẢN LÝ LỊCH SỬ ĐIỀU HƯỚNG BẰNG JS STACK (TỐI ĐA 5 MÀN HÌNH GẦN NHẤT)
    // =========================================================================
    var pageHistory = [];
    var historyIndex = -1;
    var isHistoryNavigating = false;
    var MAX_HISTORY_ITEMS = 5;

    function updateNavButtonsState() {
      var canBack = historyIndex > 0;
      var canForward = historyIndex < pageHistory.length - 1;
      
      var btnBack = document.getElementById('nav-btn-back');
      var btnFwd = document.getElementById('nav-btn-forward');
      if (btnBack) btnBack.disabled = !canBack;
      if (btnFwd) btnFwd.disabled = !canForward;
    }

    function pushHistoryState(screenId, param) {
      if (isHistoryNavigating) return;
      var state = { screenId: screenId, param: param || '' };
      if (historyIndex >= 0 && pageHistory[historyIndex].screenId === screenId && pageHistory[historyIndex].param === (param || '')) {
        return;
      }
      pageHistory = pageHistory.slice(0, historyIndex + 1);
      pageHistory.push(state);
      if (pageHistory.length > MAX_HISTORY_ITEMS) {
        pageHistory.shift();
      }
      historyIndex = pageHistory.length - 1;
      updateNavButtonsState();
    }

    function navigateHistoryBack() {
      if (historyIndex > 0) {
        historyIndex--;
        isHistoryNavigating = true;
        var prev = pageHistory[historyIndex];
        goToScreen(prev.screenId, prev.param, false);
        isHistoryNavigating = false;
        updateNavButtonsState();
      }
    }

    function navigateHistoryForward() {
      if (historyIndex < pageHistory.length - 1) {
        historyIndex++;
        isHistoryNavigating = true;
        var next = pageHistory[historyIndex];
        goToScreen(next.screenId, next.param, false);
        isHistoryNavigating = false;
        updateNavButtonsState();
      }
    }

    function closeAllSearchDropdowns() {
      var heroDropdown = document.getElementById('hero-search-dropdown');
      if (heroDropdown) heroDropdown.style.display = 'none';
      toggleHeaderSearch(false);
    }

    function toggleHeaderSearch(open) {
      var backdrop = document.getElementById('header-search-backdrop');
      var dropdown = document.getElementById('header-search-dropdown');
      var input = document.getElementById('header-search-input');
      var triggerBtn = document.getElementById('header-search-trigger-btn');
      var isCurrentlyOpen = dropdown && dropdown.style.display === 'block';
      var shouldOpen = (open !== undefined) ? Boolean(open) : !isCurrentlyOpen;

      if (backdrop && dropdown) {
        backdrop.style.display = shouldOpen ? 'block' : 'none';
        dropdown.style.display = shouldOpen ? 'block' : 'none';
        if (triggerBtn) {
          if (shouldOpen) triggerBtn.classList.add('search-trigger-active');
          else triggerBtn.classList.remove('search-trigger-active');
        }
        if (shouldOpen && input) {
          setTimeout(function() {
            input.focus();
            input.select();
          }, 60);
          onHeaderSearchInput(input.value || '');
        }
      }
    }

    // Điều hướng trực tiếp màn hình không phụ thuộc vào hashchange (khắc phục 100% iOS QuickLook)
    function goToScreen(screenId, param, addToHistory) {
      if (addToHistory === undefined) addToHistory = true;
      closeAllSearchDropdowns();

      // Đóng drawer mobile nếu đang mở
      try {
        var drawerToggle = document.getElementById('portal-drawer-toggle');
        if (drawerToggle) drawerToggle.checked = false;
      } catch (e) {}

      // Cập nhật trạng thái active cho nút Sidebar NGAY LẬP TỨC ở đầu hàm
      try {
        var allSidebarBtns = document.querySelectorAll('.sidebar-btn');
        var activeGroupId = '';
        if (screenId.indexOf('group-') === 0) {
          activeGroupId = screenId;
        } else if (screenId.indexOf('category-') === 0) {
          var cId = screenId.replace('category-', '');
          var cObj = (typeof OFFLINE_CATEGORIES !== 'undefined') ? OFFLINE_CATEGORIES.find(function(c) { return String(c.id) === cId; }) : null;
          if (cObj && cObj.groupId) activeGroupId = 'group-' + cObj.groupId;
        } else if (screenId.indexOf('business-') === 0) {
          var bId = screenId.replace('business-', '');
          var bObj = (typeof OFFLINE_BUSINESSES !== 'undefined') ? OFFLINE_BUSINESSES.find(function(b) { return String(b.id) === bId; }) : null;
          if (bObj && bObj.groupId) activeGroupId = 'group-' + bObj.groupId;
        }

        for (var s = 0; s < allSidebarBtns.length; s++) {
          var btn = allSidebarBtns[s];
          var href = btn.getAttribute('href') || '';
          if ((screenId === 'home' && (href === '#home' || href === '#')) || href === '#' + screenId || (activeGroupId && href === '#' + activeGroupId)) {
            btn.classList.add('active');
          } else {
            btn.classList.remove('active');
          }
        }
      } catch (e) {}

      var screens = document.querySelectorAll('.view-screen-page');
      for (var i = 0; i < screens.length; i++) {
        screens[i].style.display = 'none';
      }

      if (screenId === 'search') {
        var searchScreen = document.getElementById('search') || document.getElementById('search-results-screen');
        if (searchScreen) {
          searchScreen.style.display = 'block';
          try {
            renderSearchResults(param || '');
          } catch (e) {
            console.error('Error rendering search results:', e);
          }
        }
      } else if (screenId === 'saved') {
        var savedScreen = document.getElementById('saved');
        if (savedScreen) {
          savedScreen.style.display = 'block';
          try {
            renderSavedProducts();
          } catch (e) {
            console.error('Error rendering saved products:', e);
          }
        }
      } else {
        var targetEl = document.getElementById(screenId);
        if (targetEl && targetEl.classList.contains('view-screen-page')) {
          targetEl.style.display = 'block';
        } else {
          var homeEl = document.getElementById('home');
          if (homeEl) homeEl.style.display = 'block';
          screenId = 'home';
        }
      }

      if (addToHistory) {
        pushHistoryState(screenId, param);
      }
      syncAllSavedButtons();

      try {
        var newHash = (screenId === 'home') ? '#home' : (screenId === 'search' ? '#search=' + encodeURIComponent(param || '') : '#' + screenId);
        if (window.location.hash !== newHash) {
          if (window.history && window.history.replaceState) {
            window.history.replaceState(null, '', newHash);
          } else {
            window.location.hash = newHash;
          }
        }
      } catch (e) {}

      var scrollWrap = document.querySelector('.grid-main-wrapper');
      if (scrollWrap) scrollWrap.scrollTop = 0;
      window.scrollTo(0, 0);
    }

    // Xử lý tìm kiếm và kích hoạt trực tiếp màn hình kết quả
    function performSearch(query) {
      query = (query || '').trim();
      closeAllSearchDropdowns();
      if (!query) {
        goToScreen('home');
        return;
      }
      goToScreen('search', query);
    }

    function goToCategory(groupId, catId) {
      closeAllSearchDropdowns();
      catId = String(catId || '');
      groupId = String(groupId || '');

      var catScreen = document.getElementById('category-' + catId);
      if (catScreen) {
        goToScreen('category-' + catId);
        return;
      }

      if (!groupId && typeof OFFLINE_CATEGORIES !== 'undefined') {
        for (var i = 0; i < OFFLINE_CATEGORIES.length; i++) {
          if (String(OFFLINE_CATEGORIES[i].id) === catId) {
            groupId = String(OFFLINE_CATEGORIES[i].groupId || '');
            break;
          }
        }
      }
      if (!groupId && typeof OFFLINE_PRODUCTS !== 'undefined') {
        for (var j = 0; j < OFFLINE_PRODUCTS.length; j++) {
          if (String(OFFLINE_PRODUCTS[j].productCategoryId || OFFLINE_PRODUCTS[j].categoryId) === catId) {
            groupId = String(OFFLINE_PRODUCTS[j].productGroupId || OFFLINE_PRODUCTS[j].groupId || '');
            break;
          }
        }
      }

      if (groupId) {
        goToScreen('group-' + groupId);
      } else {
        var catObj = (typeof OFFLINE_CATEGORIES !== 'undefined') ? OFFLINE_CATEGORIES.find(function(c) { return String(c.id) === catId; }) : null;
        if (catObj && catObj.name) {
          performSearch(catObj.name);
          return;
        }
      }

      setTimeout(function() {
        var el = document.getElementById('cat-' + catId);
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }, 120);
    }

